import ReconnectingWebSocket from "partysocket/ws";
import {
  type ConnectionEvent,
  type ConnectionTransportCallback,
  type IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops retrying silently; the transport surfaces this by rewriting the close
// event's reason to TRANSPORT_EXHAUSTED_REASON so callers can detect the
// give-up.
export const MAX_RETRIES = 10;

// Sentinel close reason written by the transport when the retry budget is
// exhausted. `classifyCloseEvent` recognizes this as the terminal "gave-up"
// signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

/**
 * Rebuild a close event with a rewritten `reason`, preserving the remaining
 * fields (code, wasClean, type) so downstream listeners see an otherwise
 * identical event.
 */
function withReason(event: unknown, reason: string): CloseEvent {
  const source = (event ?? {}) as Partial<CloseEvent>;
  const code = typeof source.code === "number" ? source.code : 1006;
  const wasClean = Boolean(source.wasClean);
  const type = typeof source.type === "string" ? source.type : "close";
  try {
    return new CloseEvent(type, { code, reason, wasClean });
  } catch {
    // Environments without a constructable CloseEvent: fall back to a plain
    // object carrying the fields listeners rely on.
    return { type, code, reason, wasClean } as unknown as CloseEvent;
  }
}

/**
 * A WebSocket transport that wraps a reconnecting WebSocket and intercepts
 * close events.
 *
 * When the inner socket's `retryCount` has reached {@link MAX_RETRIES}, the
 * transport rewrites the close event's reason to
 * {@link TRANSPORT_EXHAUSTED_REASON} before forwarding it to registered
 * listeners — this rewrite applies even when the original close event carries a
 * server-sent reason. While `retryCount` is below {@link MAX_RETRIES}, the
 * original close reason is forwarded unchanged.
 */
export class WsTransport implements IConnectionTransport {
  readonly inner: ReconnectingWebSocket;

  // Maps each registered callback to the wrapper actually attached to the inner
  // socket, keyed per event type. Using a per-callback map deduplicates
  // registrations (adding the same callback twice attaches a single wrapper)
  // and lets a single removeEventListener() fully detach it.
  private wrappers = new Map<
    ConnectionEvent,
    Map<
      ConnectionTransportCallback<ConnectionEvent>,
      (event: unknown) => void
    >
  >();

  constructor(urlFactory: () => string) {
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    let perEvent = this.wrappers.get(event);
    if (!perEvent) {
      perEvent = new Map();
      this.wrappers.set(event, perEvent);
    }

    const cb = callback as ConnectionTransportCallback<ConnectionEvent>;
    // Deduplicate: the same callback reference only fires once per event.
    if (perEvent.has(cb)) {
      return;
    }

    const wrapper =
      event === "close"
        ? (e: unknown) => {
            // partysocket stops retrying silently once the retry budget is
            // exhausted. Rewrite the reason so callers can detect the give-up,
            // even if the server sent its own reason.
            if (this.inner.retryCount >= MAX_RETRIES) {
              cb(withReason(e, TRANSPORT_EXHAUSTED_REASON));
              return;
            }
            cb(e as never);
          }
        : (e: unknown) => cb(e as never);

    perEvent.set(cb, wrapper);
    this.inner.addEventListener(
      event,
      wrapper as EventListenerOrEventListenerObject,
    );
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const perEvent = this.wrappers.get(event);
    if (!perEvent) {
      return;
    }
    const cb = callback as ConnectionTransportCallback<ConnectionEvent>;
    const wrapper = perEvent.get(cb);
    if (!wrapper) {
      return;
    }
    this.inner.removeEventListener(
      event,
      wrapper as EventListenerOrEventListenerObject,
    );
    perEvent.delete(cb);
  }
}
