  return new ReconnectingWebSocket(urlProvider, undefined, {
    maxRetries: MAX_RETRIES,
    debug: false,
    startClosed: true,
    // long timeout -- the server can become slow when many notebooks
    // are open.
    connectionTimeout: 10_000,
  }) as unknown as IConnectionTransport;
