import { describe, expect, it, vi } from "vitest";
import {
  MAX_RETRIES,
  TRANSPORT_EXHAUSTED_REASON,
  WsTransport,
} from "./ws";

describe("WsTransport verify", () => {
  it("constants", () => {
    expect(TRANSPORT_EXHAUSTED_REASON).toBe("MARIMO_TRANSPORT_EXHAUSTED");
    expect(typeof MAX_RETRIES).toBe("number");
  });

  function setup() {
    const t = new WsTransport(() => "ws://localhost/ws");
    // Replace inner with a fake we control
    const listeners: Record<string, Array<(e: unknown) => void>> = {};
    const inner = {
      retryCount: 0,
      readyState: 3,
      addEventListener: vi.fn((ev: string, cb: (e: unknown) => void) => {
        (listeners[ev] ??= []).push(cb);
      }),
      removeEventListener: vi.fn((ev: string, cb: (e: unknown) => void) => {
        listeners[ev] = (listeners[ev] ?? []).filter((c) => c !== cb);
      }),
      reconnect: vi.fn(),
      close: vi.fn(),
      send: vi.fn(),
    };
    (t as unknown as { inner: unknown }).inner = inner;
    const fire = (ev: string, e: unknown) =>
      (listeners[ev] ?? []).forEach((c) => c(e));
    return { t, inner, listeners, fire };
  }

  it("forwards original reason when retryCount < MAX_RETRIES", () => {
    const { t, inner, fire } = setup();
    inner.retryCount = 0;
    const cb = vi.fn();
    t.addEventListener("close", cb);
    fire("close", { type: "close", code: 1006, reason: "server-reason" });
    expect(cb).toHaveBeenCalledTimes(1);
    expect(cb.mock.calls[0][0].reason).toBe("server-reason");
  });

  it("rewrites reason when exhausted, even with server reason", () => {
    const { t, inner, fire } = setup();
    inner.retryCount = MAX_RETRIES;
    const cb = vi.fn();
    t.addEventListener("close", cb);
    fire("close", { type: "close", code: 1006, reason: "server-reason" });
    expect(cb.mock.calls[0][0].reason).toBe(TRANSPORT_EXHAUSTED_REASON);
    expect(cb.mock.calls[0][0].code).toBe(1006);
  });

  it("dedupes duplicate registrations", () => {
    const { t, fire } = setup();
    const cb = vi.fn();
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    fire("close", { type: "close", code: 1000, reason: "" });
    expect(cb).toHaveBeenCalledTimes(1);
  });

  it("removeEventListener fully unregisters with a single call", () => {
    const { t, listeners, fire } = setup();
    const cb = vi.fn();
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    t.removeEventListener("close", cb);
    expect(listeners.close?.length ?? 0).toBe(0);
    fire("close", { type: "close", code: 1000, reason: "" });
    expect(cb).not.toHaveBeenCalled();
  });

  it("non-close events forwarded unchanged", () => {
    const { t, fire } = setup();
    const cb = vi.fn();
    t.addEventListener("message", cb);
    const ev = { data: "x" };
    fire("message", ev);
    expect(cb).toHaveBeenCalledWith(ev);
  });
});
