import { describe, expect, it, vi } from "vitest";
import type { SessionId } from "@/core/kernel/session";
import { RuntimeManager } from "./runtime";

vi.mock("@/core/kernel/session", () => ({
  getSessionId: () => "sid" as SessionId,
}));

describe("runtime verify", () => {
  it("probeHealth returns ok and does NOT mutate config.url on redirect", async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      redirected: true,
      url: "https://sandbox.example.com/health?x=1",
    });
    const rt = new RuntimeManager(
      { url: "https://backend.example.com/lazy?x=1", lazy: true },
      true,
    );
    const before = rt.httpURL.hostname;
    const res = await rt.probeHealth();
    expect(res).toBe(true);
    expect(rt.httpURL.hostname).toBe(before);
    expect(rt.httpURL.hostname).toBe("backend.example.com");
  });

  it("probeHealth returns false on not-ok and on throw", async () => {
    global.fetch = vi.fn().mockResolvedValue({ ok: false });
    const rt = new RuntimeManager({ url: "https://e.com", lazy: true }, true);
    expect(await rt.probeHealth()).toBe(false);
    global.fetch = vi.fn().mockRejectedValue(new Error("x"));
    expect(await rt.probeHealth()).toBe(false);
  });

  it("reconcileFromHealth mutates config.url on redirect, preserving query", async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      redirected: true,
      url: "https://sandbox.example.com/health?some=abc",
    });
    const rt = new RuntimeManager(
      { url: "https://backend.example.com/lazy?some=abc", lazy: true },
      true,
    );
    expect(await rt.reconcileFromHealth()).toBe(true);
    const ws = rt.getWsURL("s" as SessionId);
    expect(ws.hostname).toBe("sandbox.example.com");
    expect(ws.pathname).toBe("/ws");
    expect(ws.searchParams.get("some")).toBe("abc");
    document.querySelectorAll("base").forEach((el) => el.remove());
  });

  it("formatHttpURL accepts object arg", () => {
    global.fetch = vi.fn().mockResolvedValue({ ok: false });
    const rt = new RuntimeManager(
      { url: "https://e.com/p?base=1", lazy: true },
      true,
    );
    const url = rt.formatHttpURL({
      path: "api/test",
      searchParams: new URLSearchParams(),
      restrictToKnownQueryParams: false,
    });
    expect(url.pathname).toBe("/p/api/test");
    expect(url.searchParams.get("base")).toBe("1");
  });
});
