// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops retrying silently; the transport surfaces this by rewriting the close
// event's reason to TRANSPORT_EXHAUSTED_REASON so callers can detect the
// give-up.
export const MAX_RETRIES = 10;

// Sentinel close reason written by the transport when the retry budget is
// exhausted. `classifyCloseEvent` recognizes this as the terminal "gave-up"
// signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

/**
 * Rebuild a close event with a rewritten `reason`, preserving the remaining
 * fields (code, wasClean, type) so downstream listeners see an otherwise
 * identical event.
 */
function withReason(event: unknown, reason: string): CloseEvent {
  const source = (event ?? {}) as Partial<CloseEvent>;
  const code = typeof source.code === "number" ? source.code : 1006;
  const wasClean = Boolean(source.wasClean);
  const type = typeof source.type === "string" ? source.type : "close";
  try {
    return new CloseEvent(type, { code, reason, wasClean });
  } catch {
    // Environments without a constructable CloseEvent: fall back to a plain
    // object carrying the fields listeners rely on.
    return { type, code, reason, wasClean } as unknown as CloseEvent;
  }
}

/**
 * A WebSocket transport that wraps a reconnecting WebSocket and intercepts
 * close events.
 *
 * When the inner socket's `retryCount` has reached {@link MAX_RETRIES}, the
 * transport rewrites the close event's reason to
 * {@link TRANSPORT_EXHAUSTED_REASON} before forwarding it to registered
 * listeners — this rewrite applies even when the original close event carries a
 * server-sent reason. While `retryCount` is below {@link MAX_RETRIES}, the
 * original close reason is forwarded unchanged.
